import { expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ signIn, page }) => {
  // Arrange
  await signIn("member");
  const before = await page.context().cookies();
  expect(before.map((c) => c.name), "signed-in context holds a session cookie").toContain("session");

  // Act
  const response = await page.request.post("/api/auth/logout");

  // Assert
  const status = response.status();
  expect(status, await response.text()).toBe(204);
  await expectStatus(response, 204);
  const setCookie = response
    .headersArray()
    .filter((h) => h.name.toLowerCase() === "set-cookie")
    .map((h) => h.value)
    .find((value) => value.startsWith("session="));
  expect(setCookie, "logout response clears the session cookie").toBeDefined();
  expect(setCookie).toMatch(/^session=(;|$)|^session=""|Max-Age=0|Expires=Thu, 01 Jan 1970/i);
});
